"use client";

import * as React from "react";
import { useMorph } from "@/lib/cojeev-motion/use-morph";
import { cva } from "class-variance-authority";
import { cn } from "@/lib/utils";
import * as Primitive from "@radix-ui/react-dialog";
import { useDirection } from "@radix-ui/react-direction";
import { useFlowAppearance } from "@/lib/cojeev-motion/use-flow";
export type SheetProps = React.ComponentProps<typeof Primitive.Root>;
export function Sheet(props: SheetProps) {
  return <Primitive.Root {...props} />;
}
export type SheetTriggerProps = React.ComponentProps<typeof Primitive.Trigger>;
export function SheetTrigger(props: SheetTriggerProps) {
  return (
    <Primitive.Trigger
      data-slot="sheet-trigger"
      data-part="trigger"
      data-sheet-open=""
      {...props}
    />
  );
}
export type SheetPortalProps = React.ComponentProps<typeof Primitive.Portal>;
export function SheetPortal(props: SheetPortalProps) {
  return <Primitive.Portal {...props} />;
}
export type SheetOverlayProps = React.ComponentProps<typeof Primitive.Overlay>;
export function SheetOverlay({ className, ref, ...props }: SheetOverlayProps) {
  const flowRef = useFlowAppearance<HTMLDivElement>(true, ref, "fade");
  return (
    <Primitive.Overlay
      ref={flowRef}
      data-slot="sheet-overlay"
      data-part="overlay"
      className={cn(
        "v-scrim fixed inset-0 bg-[var(--v-scrim)] z-[calc(var(--z-sheet)-1)]",
        className,
      )}
      {...props}
    />
  );
}
export const sheetContentVariants = cva(
  "v-sheet [position:fixed] [top:var(--shell-inset)] [bottom:var(--shell-inset)] [width:min(480px,calc(100%_-_56px))] [background:var(--v-canvas)] [border-radius:var(--r-panel)] [padding:var(--s-6)] [z-index:var(--z-sheet)] [overflow:auto] [display:grid] grid-cols-[minmax(0,1fr)] [gap:var(--s-5)] [align-content:start] [box-shadow:var(--shadow-float),inset_0_0_0_1px_var(--v-border)]",
);
export type SheetContentProps = React.ComponentProps<
  typeof Primitive.Content
> & { showCloseButton?: boolean; /** Logical viewport edge; follows dir or DirectionProvider. */ side?: "start" | "end" };
export function SheetContent({
  className,
  ref,
  children,
  showCloseButton = false,
  side = "end",
  dir,
  ...props
}: SheetContentProps) {
  const morphRef = useMorph<HTMLDivElement>("surfaces", ref);
  const direction = useDirection(dir === "rtl" || dir === "ltr" ? dir : undefined);
  const flowRef = useFlowAppearance<HTMLDivElement>(true, morphRef, "slide-inline");
  return (
    <Primitive.Portal>
      <SheetOverlay />
      <Primitive.Content
        ref={flowRef}
        data-slot="sheet-content"
        data-part="content"
        data-side={side}
        dir={direction}
        className={cn(sheetContentVariants(), className)}
        {...props}
      >
        {children}
        {showCloseButton && (
          <SheetClose aria-label="Close" className="absolute right-4 top-4">
            ×
          </SheetClose>
        )}
      </Primitive.Content>
    </Primitive.Portal>
  );
}
export type SheetHeaderProps = React.ComponentProps<"div">;
export function SheetHeader({ className, ...props }: SheetHeaderProps) {
  return (
    <div
      data-slot="sheet-header"
      data-part="header"
      className={cn(
        "v-dialog__head flex items-start justify-between gap-[var(--s-4)]",
        className,
      )}
      {...props}
    />
  );
}
export type SheetFooterProps = React.ComponentProps<"div">;
export function SheetFooter({ className, ...props }: SheetFooterProps) {
  return (
    <div
      data-slot="sheet-footer"
      data-part="footer"
      className={cn(
        "v-dialog__actions flex gap-[var(--s-3)] justify-end mt-[var(--s-2)]",
        className,
      )}
      {...props}
    />
  );
}
export type SheetTitleProps = React.ComponentProps<typeof Primitive.Title>;
export function SheetTitle({ className, ...props }: SheetTitleProps) {
  return (
    <Primitive.Title
      data-slot="sheet-title"
      data-part="title"
      className={cn(
        "v-section font-[family-name:var(--font-display)] text-[24px] leading-[1.15] tracking-[-0.01em] pt-1.5 font-medium",
        className,
      )}
      {...props}
    />
  );
}
export type SheetDescriptionProps = React.ComponentProps<
  typeof Primitive.Description
>;
export function SheetDescription({
  className,
  ...props
}: SheetDescriptionProps) {
  return (
    <Primitive.Description
      data-slot="sheet-description"
      data-part="description"
      className={cn(
        "v-body-2 text-[15px] leading-[1.5] text-[color:var(--v-text-2)]",
        className,
      )}
      {...props}
    />
  );
}
export type SheetCloseProps = React.ComponentProps<typeof Primitive.Close>;
export function SheetClose(props: SheetCloseProps) {
  return (
    <Primitive.Close
      data-slot="sheet-close"
      data-part="close"
      data-close=""
      {...props}
    />
  );
}

@layer cojeev-states {
/* Cojeev authored subparts, state precedence, and irreducible shapes; scoped to this registry item. */
.v-scrim:where([data-slot="sheet"], [data-slot^="sheet-"]) {
  position: fixed;
  inset: 0;
  background: var(--v-scrim);
  z-index: var(--z-sheet);
}
.v-dialog__head:where([data-slot="sheet"], [data-slot^="sheet-"]) {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: var(--s-4);
}
.v-dialog__actions:where([data-slot="sheet"], [data-slot^="sheet-"]) {
  display: flex;
  gap: var(--s-2);
  justify-content: flex-end;
}
/* Scrim paint and retained close use the shared opacity-only Motion lane. */
.v-dialog__head:where([data-slot="sheet"], [data-slot^="sheet-"]) {
  align-items: start;
}
.v-dialog__head:where([data-slot="sheet"], [data-slot^="sheet-"]) .v-section {
  font-size: 24px;
  line-height: 1.15;
  padding-top: 6px;
}
.v-dialog__actions:where([data-slot="sheet"], [data-slot^="sheet-"]) {
  margin-top: var(--s-2);
  gap: var(--s-3);
}
.v-sheet:where([data-slot="sheet"], [data-slot^="sheet-"]) {
  scrollbar-gutter: stable;
}
.v-sheet:where([data-slot="sheet"], [data-slot^="sheet-"])::-webkit-scrollbar {
  width: 12px;
  height: 12px;
}
.v-sheet:where(
    [data-slot="sheet"],
    [data-slot^="sheet-"]
  )::-webkit-scrollbar-track {
  background: transparent;
  border-radius: 999px;
}
.v-sheet:where(
    [data-slot="sheet"],
    [data-slot^="sheet-"]
  )::-webkit-scrollbar-thumb {
  background: color-mix(in oklab, var(--v-ink) 34%, transparent);
  border-radius: 999px;
  border: 4px solid transparent;
  background-clip: content-box;
  min-height: 36px;
}
.v-sheet:where([data-slot="sheet"], [data-slot^="sheet-"]) {
  scrollbar-gutter: stable;
}
.v-sheet:where([data-slot="sheet"], [data-slot^="sheet-"]) {
  scrollbar-gutter: stable;
}
@keyframes v-scrim-in {
  from {
    opacity: 0;
  }
}
@media (prefers-reduced-motion: reduce) {
  [data-slot="sheet"],
  [data-slot^="sheet-"],
  [data-slot="sheet"]::before,
  [data-slot="sheet"]::after,
  [data-slot^="sheet-"]::before,
  [data-slot^="sheet-"]::after {
    animation-duration: 0s;
    animation-iteration-count: 1;
    transition-duration: 0s;
    scroll-behavior: auto;
  }
}

[data-slot="sheet-content"] {
  max-height: calc(100dvh - 2 * var(--shell-inset));
}

[data-slot="sheet-content"] { min-width:0; overscroll-behavior:contain; }
[data-slot="sheet-title"], [data-slot="sheet-description"] { overflow-wrap:anywhere; }
[data-slot="sheet-footer"] { flex-wrap:wrap; }
[data-slot="sheet-content"] { --sheet-edge:var(--shell-inset); inset-inline-end:var(--sheet-edge); }
[data-slot="sheet-content"][data-side="start"] { inset-inline-start:var(--sheet-edge); inset-inline-end:auto; }
@media (max-width:640px) { [data-slot="sheet-content"] { --sheet-edge:12px; top:12px; bottom:12px; width:calc(100% - 24px); max-height:calc(100dvh - 24px); padding:var(--s-5); } }

}
